<script setup lang="ts">
import { computed,onMounted,reactive,ref } from 'vue'
import { NAlert,NButton,NFormItem,NInput,NInputNumber,NSelect } from 'naive-ui'
import { api } from '../api'
const emit=defineEmits<{config:[value:string]}>(),catalog=ref<any[]>([]),error=ref(''),busy=ref(false)
const form=reactive({preset:'vless-reality',port:443,server_name:'',destination:'',path:'',cert_file:'/etc/caddy/cert.pem',key_file:'/etc/caddy/key.pem',choice:'x25519:native',metrics_port:21001,tunnel_token:'',owner_id:null as number|null})
const selected=computed(()=>catalog.value.find(p=>p.id===form.preset))
const connector=computed(()=>['mtg','cf-tunnel'].includes(form.preset)),users=ref<any[]>([])
const combinations=[{label:'X25519 · native',value:'x25519:native'},{label:'X25519 · xorpub',value:'x25519:xorpub'},{label:'X25519 · random',value:'x25519:random'},{label:'ML-KEM-768 · native',value:'mlkem768:native'},{label:'ML-KEM-768 · xorpub',value:'mlkem768:xorpub'},{label:'ML-KEM-768 · random',value:'mlkem768:random'}]
async function generate(){error.value='';busy.value=true;try{const {choice,...input}=form;const [authentication,appearance]=choice.split(':');const config=await api('/api/admin/protocols/preset',{method:'POST',body:JSON.stringify({...input,owner_id:input.owner_id||0,authentication,appearance})});emit('config',JSON.stringify(config,null,2));form.tunnel_token=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onMounted(async()=>{try{[catalog.value,users.value]=await Promise.all([api('/api/admin/protocols'),api('/api/admin/users')])}catch(e){error.value=(e as Error).message}})
</script>
<template><div class="preset-box"><h3>协议预设</h3><n-alert v-if="error" type="error" class="space-bottom">{{error}}</n-alert><n-form-item label="协议组合"><n-select v-model:value="form.preset" :options="catalog.map(p=>({label:p.name,value:p.id}))"/></n-form-item><div class="form-two"><n-form-item label="独立监听端口"><n-input-number v-model:value="form.port" :min="1" :max="65535" :precision="0"/></n-form-item><n-form-item v-if="selected?.reality||selected?.certificate||connector" label="TLS / REALITY 服务器名称"><n-input v-model:value="form.server_name" placeholder="cert.example.com"/></n-form-item></div><n-form-item v-if="selected?.reality" label="REALITY 握手目标（留空为服务器名称:443）"><n-input v-model:value="form.destination" placeholder="cert.example.com:443"/></n-form-item><n-form-item v-if="selected?.enc" label="ENC 认证 / 外观"><n-select v-model:value="form.choice" :options="combinations"/></n-form-item><n-form-item v-if="selected?.path" label="独立路径（留空自动生成）"><n-input v-model:value="form.path" placeholder="/独立路径"/></n-form-item><div v-if="selected?.certificate" class="form-two"><n-form-item label="节点上的证书路径"><n-input v-model:value="form.cert_file"/></n-form-item><n-form-item label="节点上的私钥路径"><n-input v-model:value="form.key_file"/></n-form-item></div><template v-if="connector"><n-form-item label="本机指标端口（每个连接器使用不同端口）"><n-input-number v-model:value="form.metrics_port" :min="1024" :max="65535" :precision="0"/></n-form-item><n-form-item v-if="form.preset==='cf-tunnel'" label="Cloudflare 命名隧道令牌"><n-input v-model:value="form.tunnel_token" type="password" show-password-on="click" :input-props="{autocomplete:'off'}"/></n-form-item><n-form-item v-else label="唯一归属用户"><n-select v-model:value="form.owner_id" :options="users.filter(u=>u.role==='user').map(u=>({label:u.email,value:u.id}))"/></n-form-item><n-alert type="info" class="space-bottom">需要在同一服务器运行 luma-connect。CF 监听端口是本机 WS 源站端口，请在 Cloudflare 将公网域名指向该 HTTP 源站，并将节点对外域名填为同一公网域名；客户端使用 443/TLS。MTProxy 每用户独立端口和密钥，Telegram 流量按采样计费；默认落地仅支持 SOCKS5。</n-alert></template><p class="muted">内核：{{selected?.kernel||'—'}}。生成会替换下方 JSON，并为 REALITY / ENC / SS2022 生成新密钥；编辑已有节点时请保留原配置，除非需要换密钥。</p><n-button :loading="busy" @click="generate">生成并填入配置</n-button></div></template>
<style scoped>.preset-box{padding:16px;margin-bottom:20px;border:1px solid var(--border,#dfe5e1);border-radius:10px}.preset-box h3{margin-top:0}</style>
